private theorem deficitCharacterGap_zero_re {lam : ℕ → ℝ} (hW : WeilPositiveFull lam) (T : ℝ) :
    (deficitCharacterGap hW 0 T).re =
      (boundaryMeasure hW).real (Ioc 0 T) - ((finite_deficitWindow T).toFinset.card : ℝ)

